/**
 * Deoxys-II-256-128 vectors, extracted by script from two files in `oasisprotocol/deoxysii`.
 *
 * | Set | Source | What it covers |
 * |---|---|---|
 * | `DEOXYS_OFFICIAL` | `testdata/Deoxys-II-256-128-official-20190608.json` | the designers' own eight |
 * | `DEOXYS_SWEEP` | `testdata/Deoxys-II-256-128.json` | every length from 0 to 255, gapless |
 *
 * **The official eight are chosen, not sampled**, and the choice is the whole reason they are enough:
 * empty/empty, associated data alone at exactly two blocks and at two blocks plus one, message alone at
 * the same two lengths, both together at 16/32 and 17/33, and one large case at 513 bytes of associated
 * data over 512 of message. Deoxys-II goes wrong at the boundary between "the region ended on a block"
 * and "it did not", separately for each of its two regions and its two domain prefixes -- and those
 * eight rows walk exactly that grid.
 *
 * **The sweep is a second implementation, which is a different kind of evidence.** It is Oasis's Go
 * implementation's output over one key and nonce, with the associated data and the message both being
 * the first `n` bytes of a fixed 256-byte string. Two implementations sharing no code and agreeing at
 * every length from 0 to 255 is what covers the lengths the official eight do not name. The key, nonce
 * and the two data strings are below; row `n` is the sealed output for length `n`.
 */

export interface DeoxysVector {
  readonly name: string;
  readonly key: string;
  readonly nonce: string;
  /** Hex, possibly empty -- the source writes JSON `null` for absent, which is not the same as "00". */
  readonly ad: string;
  readonly message: string;
  /** Ciphertext followed by the 16-byte tag. */
  readonly sealed: string;
}

